#include <cuda_runtime.h>
#include <cstdio>
#include <vector>
#include <map>
#include <fstream>
#include <cstdint>
#include <stdexcept>
#include <chrono>
#include "../gerbil-cuda/src/cuda_ds/AddKernel.cu"
#ifndef GERBIL_ROOT
#define GERBIL_ROOT "."
#endif
using namespace cuda_ds::internal;
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("require persistent diagnostic output path");std::ifstream f(std::string(GERBIL_ROOT)+"/probe.bin",std::ios::binary);uint32_t n,nu;f.read((char*)&n,4);f.read((char*)&nu,4);std::vector<uint32_t>words(n*2);f.read((char*)words.data(),words.size()*4);std::map<uint64_t,uint32_t>expected;for(unsigned i=0;i<nu;i++){uint64_t k;uint32_t c;f.read((char*)&k,8);f.read((char*)&c,4);expected[k]=c;}if(!f)throw std::runtime_error("bad fixture");uint32_t *tab,*keys,*failure;uint64_t*nf;cudaMalloc(&tab,(1024*3+16)*4);cudaMalloc(&keys,(n*2+16)*4);cudaMalloc(&failure,(n*2+16)*4);cudaMalloc(&nf,24);cudaMemset(tab,0xa5,(1024*3+16)*4);cudaMemset(keys,0xa5,(n*2+16)*4);cudaMemset(failure,0xa5,(n*2+16)*4);cudaMemset(nf,0xa5,24);auto t=tab+8;auto k=keys+8;auto fail=failure+8;auto count=nf+1;cudaMemset(t,0,1024*3*4);cudaMemcpy(k,words.data(),n*2*4,cudaMemcpyHostToDevice);cudaMemset(count,0,8);std::vector<uint32_t>back(words.size());cudaMemcpy(back.data(),k,back.size()*4,cudaMemcpyDeviceToHost);if(back!=words)throw std::runtime_error("input mismatch");cudaStream_t stream;cudaStreamCreate(&stream);cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();addToTable<2>((KeyValuePair<2>*)t,1024,(Key<2>*)k,n,stream,(Key<2>*)fail,count,n);auto err=cudaDeviceSynchronize();double sec=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();if(err!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(err));std::vector<uint32_t>table(1024*3+16),in(n*2+16),failed(n*2+16);uint64_t nc[3];cudaMemcpy(table.data(),tab,table.size()*4,cudaMemcpyDeviceToHost);cudaMemcpy(in.data(),keys,in.size()*4,cudaMemcpyDeviceToHost);cudaMemcpy(failed.data(),failure,failed.size()*4,cudaMemcpyDeviceToHost);cudaMemcpy(nc,nf,24,cudaMemcpyDeviceToHost);std::ofstream dump(argv[1],std::ios::binary);dump.write((char*)table.data(),table.size()*4);dump.write((char*)in.data(),in.size()*4);dump.write((char*)failed.data(),failed.size()*4);dump.write((char*)nc,24);dump.close();bool guards=true;for(auto*v:{&table,&in,&failed})for(unsigned j=0;j<8;j++)guards&=(*v)[j]==0xa5a5a5a5&&(*v)[v->size()-1-j]==0xa5a5a5a5;guards&=nc[0]==0xa5a5a5a5a5a5a5a5ull&&nc[2]==0xa5a5a5a5a5a5a5a5ull;std::map<uint64_t,uint32_t>got;bool duplicate=false;for(int i=0;i<1024;i++){auto off=8+i*3;auto c=table[off+2];if(c){uint64_t key=uint64_t(table[off])|(uint64_t(table[off+1])<<32);duplicate|=got.count(key);got[key]+=c;}}bool ok=guards&&nc[1]==0&&!duplicate&&got==expected;printf("GERBIL_PROBE {\"pass\":%s,\"guards\":%s,\"failed_keys\":%llu,\"duplicate_table_keys\":%s,\"expected_unique\":%u,\"actual_unique\":%zu,\"seconds\":%.9g}\n",ok?"true":"false",guards?"true":"false",(unsigned long long)nc[1],duplicate?"true":"false",nu,got.size(),sec);for(auto&x:expected)if(got[x.first]!=x.second)printf("MISMATCH key=%llu got=%u expected=%u\n",(unsigned long long)x.first,got[x.first],x.second);cudaStreamDestroy(stream);cudaFree(tab);cudaFree(keys);cudaFree(failure);cudaFree(nf);return ok?0:1;}catch(const std::exception&e){fprintf(stderr,"%s\n",e.what());return 1;}}
